import{_ as e,c as a,a2 as i,o as t}from"./chunks/framework.BnrAgU0Y.js";const s="/bllm/assets/e9c243760e002c0f9717033185faf1ec.mjR1XHov.png",A=JSON.parse('{"title":"AssemblyAI","description":"AssemblyAI","frontmatter":{"title":"AssemblyAI","description":"AssemblyAI","layout":"doc"},"headers":[],"relativePath":"langflow/integrations-assemblyai.md","filePath":"langflow/integrations-assemblyai.md"}'),r={name:"langflow/integrations-assemblyai.md"};function o(n,l,m,p,c,b){return t(),a("div",null,l[0]||(l[0]=[i('<h1 id="assemblyai" tabindex="-1">AssemblyAI <a class="header-anchor" href="#assemblyai" aria-label="Permalink to &quot;AssemblyAI&quot;">​</a></h1><p>AssemblyAI 组件允许您为您的应用应用强大的语音 AI 模型，以完成以下任务：</p><ul><li>转录音频和视频文件</li><li>格式化转录内容</li><li>生成字幕</li><li>将大型语言模型（LLMs）应用于音频文件</li></ul><p>关于 AssemblyAI 的更多信息：</p><ul><li><a href="https://www.assemblyai.com/" target="_blank" rel="noreferrer">官方网站</a></li><li><a href="https://www.assemblyai.com/docs" target="_blank" rel="noreferrer">AssemblyAI API 文档</a></li><li><a href="https://www.assemblyai.com/dashboard/signup" target="_blank" rel="noreferrer">获取免费 API 密钥</a></li></ul><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><p>您需要一个 <strong>AssemblyAI API 密钥</strong>。创建一个免费账户后，您将在您的控制面板中找到该 API 密钥。<a href="https://www.assemblyai.com/dashboard/signup" target="_blank" rel="noreferrer">在此获取免费 API 密钥</a>。</p><p>在所有需要 API 密钥的组件中，输入 <strong>AssemblyAI API 密钥</strong>。</p><p>（可选）：要使用 LeMUR 功能，您需要升级您的 AssemblyAI 账户，因为这不包含在免费账户中。</p><h2 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h2><p><img src="'+s+'" alt="AssemblyAI Components"></p><h3 id="assemblyai-start-transcript" tabindex="-1">AssemblyAI 开始转录 <a class="header-anchor" href="#assemblyai-start-transcript" aria-label="Permalink to &quot;AssemblyAI 开始转录 {#assemblyai-start-transcript}&quot;">​</a></h3><p>该组件允许您提交一个音频或视频文件进行转录。</p><p><strong>提示</strong>：您可以冻结该组件的路径，只提交一次文件。</p><ul><li><p><strong>输入</strong>：</p><ul><li>AssemblyAI API 密钥：您的 API 密钥。</li><li>音频文件：要转录的音频或视频文件。</li><li>语音模型（可选）：选择模型的类别。默认是 <em>最佳</em>。详情请参见<a href="https://www.assemblyai.com/docs/speech-to-text/speech-recognition#select-the-speech-model-with-best-and-nano" target="_blank" rel="noreferrer">语音模型</a>。</li><li>自动语言检测（可选）：启用自动语言检测。</li><li>语言（可选）：音频文件的语言。如果禁用了自动语言检测，可以手动设置。查看<a href="https://www.assemblyai.com/docs/getting-started/supported-languages" target="_blank" rel="noreferrer">支持的语言</a>获取支持的语言代码列表。</li><li>开启说话人标签（可选）：检测音频中的讲话者，并识别每个讲话者所说的内容。</li><li>预期说话人数（可选）：如果开启了说话人标签，则设置预期的说话人数。</li><li>音频文件 URL（可选）：待转录的音频或视频文件的 URL。可替代 <em>音频文件</em> 使用。</li><li>加标点（可选）：应用标点符号。默认值为 true。</li><li>格式化文本（可选）：应用大小写和文本格式化。默认值为 true。</li></ul></li><li><p><strong>输出</strong>：</p><ul><li>转录 ID：转录的 ID。</li></ul></li></ul><h3 id="assemblyai-poll-transcript" tabindex="-1">AssemblyAI Poll Transcript <a class="header-anchor" href="#assemblyai-poll-transcript" aria-label="Permalink to &quot;AssemblyAI Poll Transcript&quot;">​</a></h3><p>该组件允许您轮询转录结果。它每隔几秒钟检查一次转录的状态，直到转录完成。</p><ul><li><p><strong>输入</strong>：</p><ul><li>AssemblyAI API 密钥：您的 API 密钥。</li><li>轮询间隔（可选）：轮询的时间间隔，以秒为单位。默认值为 3 秒。</li></ul></li><li><p><strong>输出</strong>：</p><ul><li>转录结果：包含已完成转录的 AssemblyAI JSON 响应，包含文本和其他信息。</li></ul></li></ul><h3 id="assemblyai-获取字幕" tabindex="-1">AssemblyAI 获取字幕 <a class="header-anchor" href="#assemblyai-获取字幕" aria-label="Permalink to &quot;AssemblyAI 获取字幕&quot;">​</a></h3><p>该组件允许您生成 SRT 或 VTT 格式的字幕。</p><ul><li><p><strong>输入</strong>：</p><ul><li>AssemblyAI API Key: 您的 API 密钥。</li><li>Transcription Result: <code>Poll Transcript</code>（轮询转录）组件的输出。</li><li>Subtitle Format: 字幕的格式（SRT 或 VTT）。</li><li>Character per Caption (Optional): 每个字幕的最大字符数（0 表示无限制）。</li></ul></li><li><p><strong>输出</strong>：</p><ul><li>Subtitles: 一个包含 <code>subtitles</code> 字段的 JSON 响应，其中包含 SRT 或 VTT 格式的字幕。</li></ul></li></ul><h3 id="assemblyai-lemur" tabindex="-1">AssemblyAI LeMUR <a class="header-anchor" href="#assemblyai-lemur" aria-label="Permalink to &quot;AssemblyAI LeMUR&quot;">​</a></h3><p>该组件允许你使用 <a href="https://www.assemblyai.com/docs/lemur" target="_blank" rel="noreferrer">AssemblyAI LeMUR 框架</a> 将大语言模型（Large Language Models，LLMs）应用于语音数据。</p><p>LeMUR 会自动将转录结果作为附加上下文进行导入，使得将 LLM 应用于音频数据变得简便。你可以将其用于总结音频、提取见解或提问等任务。</p><ul><li><p><strong>输入</strong>：</p><ul><li>AssemblyAI API 密钥：你的 API 密钥。</li><li>转录结果：<code>Poll Transcript</code> 组件的输出。</li><li>输入提示：用于提示模型的文本。你可以在该字段中输入提示文本，或将其连接到 <code>Prompt</code> 组件。</li><li>最终模型：进行压缩后的最终提示所使用的模型。默认是 Claude 3.5 Sonnet。</li><li>温度（可选）：用于模型的温度。默认是 0.0。</li><li>最大输出大小（可选）：以 token 为单位的最大输出大小，最多 4000。默认是 2000。</li><li>端点（可选）：使用的 LeMUR 端点。默认是 &quot;task&quot;。对于 &quot;summary&quot; 和 &quot;question-answer&quot;，不需要提示输入。更多信息请参见 <a href="https://www.assemblyai.com/docs/api-reference/lemur/" target="_blank" rel="noreferrer">LeMUR API 文档</a>。</li><li>问题（可选）：用逗号分隔的问题列表。仅在 <code>Endpoint</code> 为 &quot;question-answer&quot; 时使用。</li><li>转录 ID（可选）：用逗号分隔的转录 ID 列表。LeMUR 可以在多个转录上执行操作。如果提供了该项，则忽略 <code>Transcription Result</code>。</li></ul></li><li><p><strong>输出</strong>：</p><ul><li>LeMUR 响应：生成的 LLM 响应。</li></ul></li></ul><h3 id="assemblyai-列出抄本-transcripts" tabindex="-1">AssemblyAI 列出抄本(transcripts) <a class="header-anchor" href="#assemblyai-列出抄本-transcripts" aria-label="Permalink to &quot;AssemblyAI 列出抄本(transcripts)&quot;">​</a></h3><p>该组件可以作为一个独立组件，用于列出所有先前生成的抄本。</p><ul><li><p><strong>输入</strong>：</p><ul><li>AssemblyAI API Key: 你的 API 密钥。</li><li>Limit (可选): 要检索的抄本的最大数量。默认值为 20，使用 0 代表获取全部。</li><li>Filter (可选): 按照抄本状态进行筛选。</li><li>Created On (可选): 仅获取在此日期创建的抄本（YYYY-MM-DD）。</li><li>Throttled Only (可选): 仅获取受限制的抄本，该选项会覆盖状态筛选。</li></ul></li><li><p><strong>输出</strong>：</p><ul><li>Transcript List: 包含所有抄本的信息列表，如抄本 ID、状态和数据等。</li></ul></li></ul><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><ol><li>用户输入一个音频或视频文件。</li><li>用户还可以输入一个 LLM 提示。在这个例子中，我们希望生成转录的摘要。</li><li>流程将音频文件提交进行转录处理。</li><li>流程每隔几秒检查一次转录状态，直至转录完成。</li><li>流程解析转录结果并输出转录文本。</li><li>流程同时生成字幕。</li><li>流程应用 LLM 提示生成摘要。</li><li>作为一个独立的组件，可以列出所有转录内容。</li></ol><h2 id="运行转录和语音-ai-流程" tabindex="-1">运行转录和语音 AI 流程 <a class="header-anchor" href="#运行转录和语音-ai-流程" aria-label="Permalink to &quot;运行转录和语音 AI 流程&quot;">​</a></h2><p>要运行转录和语音 AI 流程：</p><ol><li>打开 Langflow 并创建一个新项目。</li><li>将上述组件添加到您的流程画布，或者下载 <a href="https://example.com/assets/files/AssemblyAI_Flow-368be24ae9542f0b8b5253cc9d97b42f.json" target="_blank" rel="noreferrer">AssemblyAI 转录和语音 AI 流程</a>(下载链接)并<strong>导入</strong>该 JSON 文件到 Langflow。</li><li>按照流程图所示连接组件。<strong>提示</strong>：冻结 <em>Start Transcript</em>（开始转录）组件的路径，以便仅提交一次文件。</li><li>在所有需要 AssemblyAI API 密钥的组件中输入密钥（Start Transcript、Poll Transcript、Get Subtitles、LeMUR、List Transcripts）。</li><li>在 <em>Start Transcript</em> 组件中选择一个音频或视频文件。</li><li>通过点击 <em>Parse Data</em>（解析数据）组件上的<strong>播放</strong>按钮运行流程。请确保指定的模板为 <code>{text}</code>。</li><li>要生成字幕，点击 <em>Get Subtitles</em>（获取字幕）组件上的<strong>播放</strong>按钮。</li><li>要将 LLM 应用到您的音频文件，点击 <em>LeMUR</em> 组件上的<strong>播放</strong>按钮。注意，使用 LeMUR 需要升级的 AssemblyAI 账户。</li><li>要列出所有转录，点击 <em>List Transcript</em>（列出转录）组件上的<strong>播放</strong>按钮。</li></ol><h2 id="自定义​" tabindex="-1">自定义<a href="#customization" class="hash-link" aria-label="Direct link to Customization" title="Direct link to Customization">​</a> <a class="header-anchor" href="#自定义​" aria-label="Permalink to &quot;自定义&lt;a href=&quot;#customization&quot; class=&quot;hash-link&quot; aria-label=&quot;Direct link to Customization&quot; title=&quot;Direct link to Customization&quot;&gt;​&lt;/a&gt;&quot;">​</a></h2><p>流程可以通过以下方式进行自定义：</p><ol><li>修改 <em>Start Transcript</em> 组件中的参数。</li><li>修改 <em>Get Subtitles</em> 组件中的字幕格式。</li><li>修改 <em>LeMUR</em> 组件输入的 LLM（大模型，Large Language Model）提示。</li><li>修改 <em>LeMUR</em> 组件中的 LLM 参数（例如：温度）。</li></ol><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><p>如果您遇到问题：</p><ol><li>确保在所有需要使用 API 密钥的组件中正确设置了 API 密钥。</li><li>要使用 LeMUR，您需要升级您的 AssemblyAI 账户，因为这不包含在免费账户中。</li><li>验证所有组件是否在流程中正确连接。</li><li>查看 Langflow 日志以获取任何错误信息。</li></ol><p>有关更高级的用法，请参阅 <a href="https://www.assemblyai.com/docs/" target="_blank" rel="noreferrer">AssemblyAI API 文档</a>。如果您需要更多帮助，可以联系 <a href="https://www.assemblyai.com/contact/support" target="_blank" rel="noreferrer">AssemblyAI 支持</a>。</p>',40)]))}const h=e(r,[["render",o]]);export{A as __pageData,h as default};
